// Configuración
const ASUNTO_REQUERIDO = "DATOS";
const NOMBRE_ARCHIVO_REQUERIDO = "ppto_bicorps (1).csv";

return items.flatMap(item => {
  // 1. Validar que el asunto coincida (insensible a mayúsculas y espacios)
  const subject = item.json.subject;
  if (!subject || subject.trim().toLowerCase() !== ASUNTO_REQUERIDO.toLowerCase()) {
    return []; // Ignorar correo si no cumple el asunto
  }

  // 2. Buscar el adjunto con nombre EXACTO (insensible a mayúsculas)
  const attachmentEntry = Object.entries(item.binary || {}).find(
    ([key, value]) =>
      key.startsWith('attachment_') &&
      value?.fileName?.toLowerCase() === NOMBRE_ARCHIVO_REQUERIDO.toLowerCase()
  );

  if (!attachmentEntry) {
    return []; // No se encontró el archivo requerido
  }

  const att = attachmentEntry[1];

  // 3. Opcional: Validar contenido (eliminar BOM, rechazar si tiene "Exif")
  if (att.data && typeof att.data === 'string') {
    // Eliminar BOM si existe
    if (att.data.startsWith('\uFEFF')) {
      att.data = att.data.slice(1);
    }
    // Rechazar si contiene "Exif" (no es CSV válido)
    if (att.data.includes('Exif')) {
      return [];
    }
  }

  // 4. Devolver item listo para binaryToText
  return [{
    json: { ...item.json },        // Metadatos del correo
    binary: { data: att }          // Archivo adjunto listo
  }];
});

return items.map(item => {
  const src = item.json || {};

  // Normalizar claves (mayúsculas)
  const keys = {};
  for (const key of Object.keys(src)) {
    keys[key.trim().toUpperCase()] = src[key];
  }

  // Normalizar MONTO (ej: "-1.378,08" → -1378.08)
  let monto = keys["MONTO"] || "0";
  if (typeof monto === "string") {
    monto = monto.replace(/\./g, "").replace(",", ".");
  }
  monto = parseFloat(monto) || 0;

  return {
    json: {
      "CENTRO_CONTABLE": keys["CENTRO CONTABLE"] || null,
      "EJERCIICIO": keys["EJERCIICIO"] || null,
      "MES": keys["MES"] || null,
      "MONEDA": keys["MONEDA"] || null,
      "CENTRO_DE_COSTO": keys["CENTRO DE COSTO"] || null,
      "CUENTA": keys["CUENTA"] || null,
      "MONTO": monto
    }
  };
});

// Parsear CSV robusto: detecta delimitador (; o ,), normaliza BOM y saltos de línea,
// procesa todos los items entrantes (por si hay múltiples adjuntos).
const output = [];

for (const item of items) {
  const csvText = item.json?.data;
  if (!csvText || typeof csvText !== 'string') continue;

  // Quitar BOM y normalizar saltos de línea
  let text = csvText.replace(/^\uFEFF/, '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');

  // Separar líneas y quitar líneas vacías al principio/final
  const lines = text.split('\n').map(l => l.trim()).filter(l => l.length > 0);
  if (lines.length === 0) continue;

  // Detectar delimitador por la primera línea (header)
  const first = lines[0];
  const semiCount = (first.match(/;/g) || []).length;
  const commaCount = (first.match(/,/g) || []).length;
  const delim = semiCount > commaCount ? ';' : ',';

  // Encabezados
  const headers = first.split(delim).map(h => h.trim().replace(/^"|"$/g, ''));

  // Procesar filas
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(delim).map(v => v.trim().replace(/^"|"$/g, ''));
    const obj = {};
    for (let h = 0; h < headers.length; h++) {
      obj[headers[h]] = values[h] ?? '';
    }
    output.push({ json: obj });
  }
}

return output;
